// Step 3: Defense-in-Depth Expiry Check (60-second limit)
const expiresAtTime = new Date($input.item.json.expires_at).getTime();
const currentTime = Date.now();
const isExpired = currentTime >= expiresAtTime;

return {
  json: {
    ...$input.item.json,
    _is_expired: isExpired
  }
};

