// Step 4: Prepare Samaj Setu Branded Responsive Email (HTML & Text)
const item = $input.item.json;
const name = item.name || 'Citizen / Official';
const otp = item.otp;
const requestId = item.request_id;
const currentYear = new Date().getFullYear();

// Split OTP digits for accessible rendering
const formattedOtp = otp.split('').join(' ');

const htmlBody = `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Samaj Setu Verification Code</title>
  <style>
    body { margin: 0; padding: 0; background-color: #f6fbf8; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; color: #17231b; -webkit-font-smoothing: antialiased; }
    .wrapper { width: 100%; table-layout: fixed; background-color: #f6fbf8; padding: 40px 0; }
    .container { max-width: 580px; margin: 0 auto; background-color: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 10px 25px -5px rgba(11, 93, 42, 0.1), 0 8px 10px -6px rgba(11, 93, 42, 0.05); border: 1px solid #ddebe2; }
    .header { background: linear-gradient(135deg, #0B5D2A 0%, #168a45 50%, #083c1b 100%); padding: 36px 32px; text-align: center; color: #ffffff; }
    .logo-badge { display: inline-flex; align-items: center; justify-content: center; width: 54px; height: 54px; border-radius: 14px; background: rgba(255, 255, 255, 0.15); border: 1px solid rgba(255, 255, 255, 0.25); margin-bottom: 12px; font-size: 26px; }
    .brand-title { margin: 0; font-size: 24px; font-weight: 800; letter-spacing: -0.02em; color: #ffffff; }
    .brand-sub { margin: 4px 0 0 0; font-size: 12px; font-weight: 600; color: #eaf7ef; text-transform: uppercase; letter-spacing: 0.08em; }
    .content { padding: 36px 32px 28px 32px; }
    .greeting { font-size: 17px; font-weight: 600; color: #0B5D2A; margin: 0 0 14px 0; }
    .lead-text { font-size: 15px; line-height: 1.6; color: #475569; margin: 0 0 26px 0; }
    .otp-card { background: #f6fbf8; border: 2px dashed #168a45; border-radius: 12px; padding: 24px 20px; text-align: center; margin: 0 0 26px 0; }
    .otp-label { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.12em; color: #0B5D2A; margin: 0 0 8px 0; }
    .otp-digits { font-family: 'Courier New', Courier, monospace; font-size: 38px; font-weight: 800; letter-spacing: 0.25em; color: #0B5D2A; margin: 0; }
    .expiry-badge { display: inline-block; background-color: #fee2e2; border: 1px solid #fca5a5; color: #991b1b; padding: 6px 14px; border-radius: 9999px; font-size: 12px; font-weight: 700; margin-top: 14px; }
    .advisory-box { background-color: #eaf7ef; border-left: 4px solid #168a45; border-radius: 0 8px 8px 0; padding: 14px 18px; margin: 0 0 28px 0; }
    .advisory-title { font-size: 13px; font-weight: 700; color: #0B5D2A; margin: 0 0 4px 0; }
    .advisory-item { font-size: 12px; line-height: 1.5; color: #2d4a36; margin: 2px 0; }
    .footer { background-color: #f6fbf8; border-top: 1px solid #ddebe2; padding: 24px 32px; text-align: center; }
    .footer-text { font-size: 12px; color: #66736b; line-height: 1.5; margin: 0 0 6px 0; }
    .request-meta { font-size: 11px; font-family: monospace; color: #88998e; margin: 0; }
  </style>
</head>
<body>
  <div class="wrapper">
    <div class="container">
      <div class="header">
        <div class="logo-badge">🏛️</div>
        <h1 class="brand-title">Samaj Setu</h1>
        <p class="brand-sub">Samaj Setu — SIH26043 | Community Innovation Platform</p>
      </div>
      <div class="content">
        <p class="greeting">Hello ${name},</p>
        <p class="lead-text">
          You are registering your official account on Samaj Setu. Please use the One-Time Password (OTP) below to verify your email address.
        </p>
        <div class="otp-card">
          <div class="otp-label">Your Verification Code</div>
          <div class="otp-digits">${formattedOtp}</div>
          <div class="expiry-badge">⏱️ Strictly Valid for 60 Seconds</div>
        </div>
        <div class="advisory-box">
          <div class="advisory-title">Important Security Instructions</div>
          <p class="advisory-item">• Do not disclose this code to anyone, including Samaj Setu support.</p>
          <p class="advisory-item">• Samaj Setu will never ask for your verification code via phone or chat.</p>
          <p class="advisory-item">• If you did not initiate this registration request, please ignore this email.</p>
        </div>
      </div>
      <div class="footer">
        <p class="footer-text">This is an automated system notification from Samaj Setu — SIH26043.</p>
        <p class="request-meta">Reference ID: ${requestId} • ${currentYear}</p>
      </div>
    </div>
  </div>
</body>
</html>
`;

const textBody = `Hello ${name},

Welcome to Samaj Setu — SIH26043.

Your One-Time Password (OTP) for email verification is:

${otp}

IMPORTANT: This OTP is strictly valid for 60 SECONDS (1 minute).

Security Guidelines:
- Do not share this OTP with anyone.
- Samaj Setu personnel will never request your OTP.
- If you did not request this verification, please safely ignore this email.

Reference ID: ${requestId}
Samaj Setu — SIH26043 Community Innovation Platform`;

return {
  json: {
    email: item.email,
    request_id: requestId,
    subject: 'Samaj Setu — Your Email Verification OTP',
    html_body: htmlBody,
    text_body: textBody
  }
};

